refentry.refsect1:
  &reftitle.examples;



    Exemple avec collator_set_strength


<?php
$arr  = array( 'aò', 'Ao', 'ao' );
$coll = collator_create( 'en_US' );

// Trie un tableau avec le niveau par défaut
collator_sort( $coll, $arr );
var_export( $arr );

// Tri un tableau avec le niveau primaire
collator_set_strength( $coll, Collator::PRIMARY );
collator_sort( $coll, $arr );
var_export( $arr );
?>


    &example.outputs;


array (
  0 => 'ao',
  1 => 'Ao',
  2 => 'aò',
)
array (
  0 => 'aò',
  1 => 'Ao',
  2 => 'ao',
)




    Définir la force via la clé d'extension de locale Unicode ks

     La force de collation peut aussi être définie à la construction du
     Collator en utilisant la clé d'extension de locale
     Unicode ks dans l'identifiant de locale.
     La correspondance entre les valeurs de ks et les
     constantes de Collator est la suivante :






        Valeur de la clé de locale
        Constante de Collator




ks-level1Collator::PRIMARY

ks-level2Collator::SECONDARY

ks-level3Collator::TERTIARY

ks-level4Collator::QUATERNARY

ks-identicCollator::IDENTICAL




     Collator::DEFAULT_STRENGTH n'a pas d'équivalent ks-*
     et doit être définie par programmation via collator_set_strength.



<?php

$textStyle  = "\u{263A}\u{FE0E}"; // U+263A + U+FE0E (sélecteur de présentation textuelle)
$emojiStyle = "\u{263A}\u{FE0F}"; // U+263A + U+FE0F (sélecteur de présentation emoji)

// Collator par défaut (force TERTIARY) : les sélecteurs de variation sont ignorés.
$collDefault = new Collator('en_US');
var_dump($collDefault->compare($textStyle, $emojiStyle) === 0); // bool(true)

// Force IDENTICAL via setStrength().
$coll1 = new Collator('en_US');
$coll1->setStrength(Collator::IDENTICAL);
var_dump($coll1->compare($textStyle, $emojiStyle) === 0); // bool(false)

// Équivalent : force IDENTICAL via la clé d'extension de locale ks.
$coll2 = new Collator('en_US-u-ks-identic');
var_dump($coll2->compare($textStyle, $emojiStyle) === 0); // bool(false)

?>


    &example.outputs;


bool(true)
bool(false)
bool(false)
